// Password-cracking map (generated by scripts/build-cpts.mjs). Without scripts
// the page is the whole map: every node's explanation is a <details>, the
// workflow is a plain list, and the reference tables are plain tables. This
// adds:
//  - the workflow walk: the steps become tabs over one panel, with Previous /
//    Next, and the map marks, opens and scrolls to the node for each step;
//  - copy buttons on the command blocks;
//  - open / close all, and a flash on the phase a loop link jumps to;
//  - a live filter on each reference table.
import { initCommandPalette } from "../../js/command-palette.js?v=search2";
import { initSiteHeader } from "../../js/site-header.js?v=276fa973-header";
import { initTheme } from "../../js/theme.js?v=276fa973";
import { copyTextToClipboard } from "../../js/markdown.js?v=276fa973-th";
import { initHeroDither } from "../../js/hero-dither.js?v=276fa973-idle";

const reduceMotion = () => window.matchMedia("(prefers-reduced-motion: reduce)").matches;

const addCopy = (pre) => {
  if (pre.parentElement?.classList.contains("pc-cmd-wrap")) return;
  const wrap = document.createElement("div");
  wrap.className = "pc-cmd-wrap";
  pre.before(wrap);
  wrap.append(pre);
  const btn = document.createElement("button");
  btn.type = "button";
  btn.className = "pc-copy";
  btn.textContent = "Copy";
  btn.addEventListener("click", () => {
    const text = (pre.querySelector("code")?.textContent || "").trim();
    void copyTextToClipboard(text, btn, "Copy");
  });
  wrap.append(btn);
};

const openNode = (li) => {
  const box = li.querySelector(":scope > .pc-node-box");
  if (box) box.open = true;
};

const initWalk = () => {
  const walk = document.getElementById("pc-walk");
  if (!walk) return;
  const steps = [...walk.querySelectorAll(".pc-walk-step")];
  if (!steps.length) return;
  const controls = walk.querySelector(".pc-walk-controls");
  const prev = walk.querySelector('[data-walk="prev"]');
  const next = walk.querySelector('[data-walk="next"]');
  const pos = walk.querySelector(".pc-walk-pos");

  const panel = document.createElement("div");
  panel.className = "pc-walk-panel";
  panel.id = "pc-walk-panel";
  panel.setAttribute("aria-live", "polite");
  walk.querySelector(".pc-walk-steps").after(panel);

  let current = -1;
  const show = (index, { scroll = true } = {}) => {
    current = Math.max(0, Math.min(steps.length - 1, index));
    const step = steps[current];
    steps.forEach((s, i) => {
      const tab = s.querySelector(".pc-walk-tab");
      if (i === current) tab.setAttribute("aria-current", "step");
      else tab.removeAttribute("aria-current");
      s.classList.toggle("is-done", i < current);
    });

    const title = document.createElement("h3");
    title.textContent = `${current + 1}. ${step.querySelector(".pc-walk-tab span:last-child")?.textContent || ""}`;
    const card = step.querySelector(".pc-walk-card").cloneNode(true);
    card.classList.remove("pc-walk-card");
    panel.replaceChildren(title, card);
    for (const pre of panel.querySelectorAll("pre.pc-cmd")) addCopy(pre);

    pos.textContent = `Step ${current + 1} of ${steps.length}`;
    prev.disabled = current === 0;
    next.disabled = current === steps.length - 1;

    for (const node of document.querySelectorAll(".pc-node.is-current")) node.classList.remove("is-current");
    const node = document.getElementById(`pcnode-${step.dataset.node}`);
    if (node) {
      node.classList.add("is-current");
      openNode(node);
      if (scroll) node.scrollIntoView({ behavior: reduceMotion() ? "auto" : "smooth", block: "center" });
    }
  };

  for (const [i, step] of steps.entries()) {
    step.querySelector(".pc-walk-tab").addEventListener("click", (event) => {
      event.preventDefault();
      show(i, { scroll: false });
    });
  }
  prev.addEventListener("click", () => show(current - 1));
  next.addEventListener("click", () => show(current + 1));

  for (const badge of document.querySelectorAll(".pc-node.is-step")) {
    badge.querySelector(":scope > .pc-node-box")?.addEventListener("toggle", (event) => {
      if (!event.target.open) return;
      const n = Number(badge.dataset.step) - 1;
      if (n !== current) show(n, { scroll: false });
    });
  }

  walk.classList.add("is-enhanced");
  controls.hidden = false;
  show(0, { scroll: false });
};

const initMapTools = () => {
  const tools = document.querySelector(".pc-map-tools");
  if (!tools) return;
  tools.hidden = false;
  for (const btn of tools.querySelectorAll("[data-expand]")) {
    btn.addEventListener("click", () => {
      const open = btn.dataset.expand === "open";
      for (const box of document.querySelectorAll(".pc-node-box")) box.open = open;
    });
  }
};

const initLoops = () => {
  for (const link of document.querySelectorAll(".pc-next")) {
    link.addEventListener("click", () => {
      const phase = document.getElementById(`pcphase-${link.dataset.to}`);
      if (!phase || reduceMotion()) return;
      phase.classList.remove("is-flash");
      void phase.offsetWidth;
      phase.classList.add("is-flash");
    });
  }
};

// Live filter on each reference table: rows carry data-search (lowercased).
const initRefFilters = () => {
  for (const input of document.querySelectorAll("[data-ref-filter]")) {
    const id = input.dataset.refFilter;
    const table = document.querySelector(`[data-ref-table="${id}"]`);
    const count = document.querySelector(`[data-ref-count="${id}"]`);
    const empty = document.querySelector(`[data-ref-empty="${id}"]`);
    if (!table) continue;
    const rows = [...table.querySelectorAll("tbody tr")];
    const total = rows.length;
    const apply = () => {
      const q = input.value.trim().toLowerCase();
      let shown = 0;
      for (const row of rows) {
        const match = !q || (row.dataset.search || "").includes(q);
        row.hidden = !match;
        if (match) shown += 1;
      }
      if (count) count.textContent = q ? `${shown} of ${total}` : `${total}`;
      if (empty) empty.hidden = shown !== 0;
    };
    input.addEventListener("input", apply);
    apply();
  }
};

document.addEventListener("DOMContentLoaded", () => {
  initCommandPalette();
  initSiteHeader();
  initTheme();
  initHeroDither();
  for (const pre of document.querySelectorAll(".pc-map pre.pc-cmd")) addCopy(pre);
  initMapTools();
  initLoops();
  initWalk();
  initRefFilters();
});
